using System.ComponentModel.DataAnnotations.Schema;
using System.Text.Json;
using PMS.API.Shared.Common.Models;

namespace PMS.API.Modules.Sla.Models;

/// <summary>
/// Audit trail of scheduled events, reminders, warnings, breach evaluations,
/// and escalations triggered for an SLA instance.
/// </summary>
public class SlaEvent : BaseEntity
{
    public Guid InstanceId { get; set; }

    public SlaEventType EventType { get; set; }

    public DateTime? ScheduledAtUtc { get; set; }

    public DateTime? ExecutedAtUtc { get; set; }

    /// <summary>
    /// Background job ID generated by Hangfire for this event.
    /// </summary>
    public string? HangfireJobId { get; set; }

    public SlaEventStatus Status { get; set; } = SlaEventStatus.Scheduled;

    /// <summary>
    /// Workflow stage expected when this event executes.
    /// If the instance transitioned to another stage, the event is marked Skipped.
    /// </summary>
    public string StageAtExecution { get; set; } = "Default";

    /// <summary>
    /// Roles targeted by this notification/escalation event (JSON array).
    /// </summary>
    public string TargetRolesJson { get; set; } = "[]";

    /// <summary>
    /// Resolved employee GUIDs targeted by this event (JSON array).
    /// </summary>
    public string TargetRecipientIdsJson { get; set; } = "[]";

    /// <summary>
    /// Execution output, state transition logs, or error details.
    /// </summary>
    public string? ExecutionLog { get; set; }

    public int RetryCount { get; set; } = 0;

    /// <summary>
    /// Unique idempotency key to prevent duplicate scheduled/executed events (e.g. "sla:{instanceId}:esc-l1").
    /// </summary>
    public string? IdempotencyKey { get; set; }

    public virtual SlaInstance? Instance { get; set; }

    [NotMapped]
    public IReadOnlyList<string> TargetRoles
    {
        get => DeserializeList<string>(TargetRolesJson);
        set => TargetRolesJson = JsonSerializer.Serialize(value ?? []);
    }

    [NotMapped]
    public IReadOnlyList<Guid> TargetRecipientIds
    {
        get => DeserializeList<Guid>(TargetRecipientIdsJson);
        set => TargetRecipientIdsJson = JsonSerializer.Serialize(value ?? []);
    }

    private static List<T> DeserializeList<T>(string json)
    {
        if (string.IsNullOrWhiteSpace(json)) return [];
        try
        {
            return JsonSerializer.Deserialize<List<T>>(json) ?? [];
        }
        catch
        {
            return [];
        }
    }
}
